"use strict";(self.webpackChunkdocs_appkeyid=self.webpackChunkdocs_appkeyid||[]).push([["9570"],{7661(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>h,frontMatter:()=>s,contentTitle:()=>r,toc:()=>d,assets:()=>c});var i=JSON.parse('{"id":"concepts/use-cases/who-is-the-person","title":"Who Is the Person?","description":"Who are you really?","source":"@site/docs/concepts/use-cases/who-is-the-person.mdx","sourceDirName":"concepts/use-cases","slug":"/concepts/use-cases/who-is-the-person","permalink":"/AppKeyIdDocs/docs/concepts/use-cases/who-is-the-person","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1},"sidebar":"conceptsSidebar","previous":{"title":"Use Cases","permalink":"/AppKeyIdDocs/docs/category/use-cases"},"next":{"title":"Why AI Breaks Digital Trust","permalink":"/AppKeyIdDocs/docs/concepts/use-cases/why-ai-breaks-digital"}}'),a=t(4848),o=t(8453);let s={sidebar_position:1},r="Who Is the Person?",c={},d=[{value:"Problem of Trust",id:"problem-of-trust",level:2},{value:"Enabling technologies",id:"enabling-technologies",level:2},{value:"New Class of Attested Applications",id:"new-class-of-attested-applications",level:2},{value:"Proof of Human Presence",id:"proof-of-human-presence",level:3},{value:"Confidential Communication",id:"confidential-communication",level:3},{value:"Verified Acknowledgements",id:"verified-acknowledgements",level:3},{value:"Group Enrollment",id:"group-enrollment",level:3},{value:"Time and Attendance",id:"time-and-attendance",level:3},{value:"Event Tickets",id:"event-tickets",level:3},{value:"Access Control",id:"access-control",level:3},{value:"Approval Workflows",id:"approval-workflows",level:3},{value:"Authenticated QR Codes",id:"authenticated-qr-codes",level:3},{value:"Chain of Custody",id:"chain-of-custody",level:3}];function l(e){let n={h1:"h1",h2:"h2",h3:"h3",header:"header",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"who-is-the-person",children:"Who Is the Person?"})}),"\n",(0,a.jsx)(n.p,{children:"Who are you really?"}),"\n",(0,a.jsx)(n.p,{children:"Computers have become very good at moving information from one place to another.\nThey have become much less reliable at proving who is actually participating in the exchange."}),"\n",(0,a.jsx)("div",{align:"center",children:(0,a.jsx)("img",{src:t(6888).A,alt:"Who is the Person?",style:{maxWidth:"500px",width:"100%",height:"auto"}})}),"\n",(0,a.jsx)(n.h2,{id:"problem-of-trust",children:"Problem of Trust"}),"\n",(0,a.jsx)(n.p,{children:"Many applications depend on knowing the identity of a person before an action can be trusted.\nApproving a contract, acknowledging a policy, opening a secure door, authorizing a payment,\naccessing medical records, or admitting someone to an event all require more than simply knowing\nthat a message was delivered. They require knowing who performed the action, or acknowledged the\ncommunication."}),"\n",(0,a.jsx)(n.p,{children:"Historically, this has been difficult to achieve over the Internet. Passwords identify accounts,\nnot people. Email addresses and phone numbers can be stolen or transferred. Even two-factor\nauthentication ultimately proves possession of a device rather than the identity of the\nindividual using it."}),"\n",(0,a.jsx)(n.p,{children:"Biometric authentication has existed for many years, but until recently it was largely been\nconfined to unlocking a device. There was no widely adopted, standards-based mechanism for\ncarrying that proof of identity across the network to another computer."}),"\n",(0,a.jsx)(n.h2,{id:"enabling-technologies",children:"Enabling technologies"}),"\n",(0,a.jsx)(n.p,{children:"Two developments have changed this."}),"\n",(0,a.jsx)(n.p,{children:"The first is that nearly every modern smartphone now contains secure biometric hardware.\nFingerprint and facial recognition have become commonplace, and users routinely authenticate\nthemselves with them."}),"\n",(0,a.jsx)(n.p,{children:"The second is the adoption of the FIDO2 passkey standard. A passkey stores a private cryptographic\nkey on the user\u2019s device. The key never leaves the device and can only be used after the user\nhas authenticated locally, typically through biometrics. The corresponding public key allows a\nremote server to verify the user\u2019s identity without relying on passwords or shared secrets."}),"\n",(0,a.jsx)(n.p,{children:"Together, these technologies make something practical that was previously difficult: a remote\nsystem can obtain cryptographic proof that a specific individual authorized a specific action."}),"\n",(0,a.jsxs)(n.p,{children:["This capability is what we call ",(0,a.jsx)(n.strong,{children:"Attested Communication."})]}),"\n",(0,a.jsx)(n.p,{children:"Attested Communication extends authentication beyond the login process. Instead of merely proving who\nsigned into a service, it proves who created a message, acknowledged a document, approved a request,\nscanned a QR code, or performed another meaningful action. Every attestation is cryptographically\nbound to the user\u2019s identity, the specific action, and the time at which it occurred. Optionally,\nadditional information such as location or comments may also be recorded."}),"\n",(0,a.jsxs)(n.p,{children:["Authentication answers the question, ",(0,a.jsx)(n.strong,{children:"Who logged in?"})," Attested Communication answers the more useful question,\n",(0,a.jsx)(n.strong,{children:"Who performed this specific action?"})]}),"\n",(0,a.jsx)(n.h2,{id:"new-class-of-attested-applications",children:"New Class of Attested Applications"}),"\n",(0,a.jsx)(n.p,{children:"That distinction enables an entirely new class of applications."}),"\n",(0,a.jsx)(n.h3,{id:"proof-of-human-presence",children:"Proof of Human Presence"}),"\n",(0,a.jsx)(n.p,{children:"Determine that you are communicating with a real, verified individual rather than an AI agent,\nimpersonator, or compromised account. The recipient authenticates with a passkey before responding,\nproviding cryptographic proof of identity."}),"\n",(0,a.jsx)(n.h3,{id:"confidential-communication",children:"Confidential Communication"}),"\n",(0,a.jsx)(n.p,{children:"Send a message that can only be opened by a specific verified individual.\nEven if the message or link is forwarded, intercepted, or copied, only the intended recipient can\nauthenticate and access its contents."}),"\n",(0,a.jsx)(n.h3,{id:"verified-acknowledgements",children:"Verified Acknowledgements"}),"\n",(0,a.jsx)(n.p,{children:"Publish a message, policy, or announcement and record exactly who acknowledged it. Instead of relying\non delivery receipts or read receipts, the sender receives a verifiable list of authenticated recipients."}),"\n",(0,a.jsx)(n.h3,{id:"group-enrollment",children:"Group Enrollment"}),"\n",(0,a.jsx)(n.p,{children:"Allow users to securely join a team, organization, event, or mailing list by scanning an\nauthenticated QR code or following a secure invitation. Every membership is tied to a verified identity."}),"\n",(0,a.jsx)(n.h3,{id:"time-and-attendance",children:"Time and Attendance"}),"\n",(0,a.jsx)(n.p,{children:"Replace traditional time clocks with authenticated check-in and check-out. Each attendance record\nis signed by the employee\u2019s passkey, providing an accurate and auditable record of who was present\nand when."}),"\n",(0,a.jsx)(n.h3,{id:"event-tickets",children:"Event Tickets"}),"\n",(0,a.jsx)(n.p,{children:"Issue digital tickets that are bound to a verified individual rather than to a barcode alone.\nAdmission requires passkey authentication, preventing ticket sharing, duplication, and impersonation."}),"\n",(0,a.jsx)(n.h3,{id:"access-control",children:"Access Control"}),"\n",(0,a.jsx)(n.p,{children:"Grant access to buildings, equipment, restricted areas, or digital resources only after the user\nhas authenticated. Every access event is recorded as a verified action."}),"\n",(0,a.jsx)(n.h3,{id:"approval-workflows",children:"Approval Workflows"}),"\n",(0,a.jsx)(n.p,{children:"Require authenticated approval of contracts, purchase orders, engineering changes, compliance documents,\nor safety inspections. Every approval is attributable to a specific verified individual."}),"\n",(0,a.jsx)(n.h3,{id:"authenticated-qr-codes",children:"Authenticated QR Codes"}),"\n",(0,a.jsx)(n.p,{children:"Transform an ordinary QR code into a secure action. Scanning the code is only the first step; the\nuser must authenticate before the action is performed, whether that action is logging in, unlocking a door,\njoining a group, making a payment, or confirming delivery."}),"\n",(0,a.jsx)(n.h3,{id:"chain-of-custody",children:"Chain of Custody"}),"\n",(0,a.jsx)(n.p,{children:"Maintain a complete, verifiable record showing who created, viewed, acknowledged, approved, or\nmodified information throughout its lifetime. Every step is cryptographically authenticated and\ncan be independently audited."}),"\n",(0,a.jsx)(n.p,{children:"These applications appear different on the surface, but they all rely on the same underlying capability:\nthe ability to associate a meaningful action with a verified human identity."}),"\n",(0,a.jsx)(n.p,{children:"AppKeyId is a platform built around this idea. It combines FIDO2 passkeys with messages,\ndocuments, QR codes, approvals, tickets, and other communication objects so that every\nimportant interaction can be authenticated by the individual performing it. The result is\na verifiable chain of communication in which identity is no longer inferred from an account\nor a password, but is cryptographically attested at the moment each action occurs."}),"\n",(0,a.jsx)(n.p,{children:"The widespread adoption of passkeys marks more than the replacement of passwords.\nIt introduces a new primitive for distributed systems: the ability to prove, cryptographically,\nthat a particular person performed a particular action. Attested Communication is the practical\napplication of that primitive."})]})}function h(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},6888(e,n,t){t.d(n,{A:()=>i});let i=t.p+"assets/images/person-f42ca83c9c4f28c7c847d43c75300679.png"},8453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var i=t(6540);let a={},o=i.createContext(a);function s(e){let n=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(o.Provider,{value:n},e.children)}}}]);